Proof.
  intros segs m A bs H. pose proof H as [[Hwf _] _]. cbn in Hwf. destruct Hwf as [Hl _].
  pose proof (rw_cells_split_CB segs m A [] 192 bs [] [4;4;16;16;16;16;16;16;16;20;4;48]%nat H eq_refl) as S.
  cbn [mk_CB_cells app] in S. rewrite !skipn_skipn in S. cbn [Nat.add] in S. unfold gsub.
  peel S S0. peel S S1. peel S S2. peel S S3. peel S S4. peel S S5. peel S S6. peel S S7. peel S S8.
  peel S T0. peel S T1. rename S into T2.
  rewrite !skipn_O in *.
  apply (rw_cells_CB4_C4 segs m _ [] _ []) in S0. apply (rw_cells_CB4_C4 segs m _ [] _ []) in S1.
  apply (rw_cells_CB4_C4 segs m _ [] _ []) in T1.
  cbn [app] in *.
  assert (J : rw_cells segs m A ([C4 (wof (firstn 4 bs))] ++ [C4 (wof (firstn 4 (skipn 4 bs)))])).
  { apply (proj2 (rw_cells_app segs m A _ _)). split; [exact S0|]. cbn [cells_size csize Nat.add].
    change (Z.of_nat 4) with 4. exact S1. }
  cbn [app] in J.
  repeat match goal with H : rw_cells _ _ ?a _ |- _ => progress (ring_simplify a in H) end.
  refine (conj J _).
  repeat (split; [first [eassumption | match goal with H : rw_cells _ _ ?a ?c |- rw_cells _ _ ?b ?c => replace b with a by lia; exact H end]|]).
  first [eassumption | match goal with H : rw_cells _ _ ?a ?c |- rw_cells _ _ ?b ?c => replace b with a by lia; exact H end].
Qed.
