  #[using="IMG AMS NEED0 MPIINIT"] Lemma A_ecp_group_init_walk : ecp_group_init_stmtA asegs R HIA MT A_ECP_GROUP_INIT.
  Proof.
    unfold ecp_group_init_stmtA, A_ECP_GROUP_INIT, ECP_GROUP_SIZE.
    intros until junk. intros HH HG AL8 POS ST LOS SLO TOP SPA DS MI OA CWA ->.
    pose proof (hcs_ok asegs R HIA h) as CSOK.
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    pose proof (art_alwf asegs R HIA) as ALWF'. unfold al_wf in ALWF'.
    pose proof IMG as IMG'. unfold asan_img_ok in IMG'.
    pose proof (art_lo asegs R HIA) as ALO. pose proof alloc_ceiling_pos as ACP.
    pose proof (hcs_stack asegs R HIA h) as SCS0.
    pose proof (hm_top asegs R HIA h LB LF m HH) as HTOP.
    pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. cbn [Z.pow Z.of_N Pos.pow] in SPR.
    assert (LO0 : 0 <= lo) by lia.
    assert (SCS : crange (hcs asegs R HIA h) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| lia| lia]).
    pose proof (rw_cells_bound _ _ _ _ HG) as GB. cbn [cells_size csize Nat.add] in GB.
    assert (JL : length junk = 192%nat) by (destruct HG as [[WF _] _]; cbn in WF; destruct WF as [WF _]; exact WF).
    destruct (grp_chunks_of_bytesA _ _ _ _ HG) as (HD & S1 & S2 & S3 & S4 & S5 & S6 & S7 & T0 & T1 & T2). clear HG.
    apply mpi_cells_of_bytes in S1. apply mpi_cells_of_bytes in S2. apply mpi_cells_of_bytes in S3. apply mpi_cells_of_bytes in S4.
    apply mpi_cells_of_bytes in S5. apply mpi_cells_of_bytes in S6. apply mpi_cells_of_bytes in S7.
    pose proof (munch_refl [(A, A + 192); (lo, bv_unsigned sp)] m) as MU.
    pose proof (wmono_refl asegs m) as WM.
    pose proof (hm_abase asegs R HIA h LB LF m HH) as AB.
    carve_frame 32%nat ST.
    unfold mpi_cells in S1, S2, S3, S4, S5, S6, S7.
    (* [comment removed for export] *)
    zstep. zstep. zstep. zstep.
    zstep. if_cases K0; zify_cond K0; [exfalso; rewrite ?unsigned_lit in K0 by qlia; clear - K0 POS; lia|]. clear K0.
    assert (AL7 : Z.land A 7 = 0)
      by (change 7 with (Z.ones 3); rewrite Z.land_ones by lia; first [exact AL8 | clear - AL8; Z.div_mod_to_equations; lia]).
    zstep. zstep. zstep. if_cases KA; zify_cond KA; [exfalso; clear - KA AL7; rewrite ?AL7 in KA; rewrite ?Zmod_0_l in KA; lia|]. clear KA.
    pose proof (abase_got _ _ _ AB) as GOT. pose proof (abase_gsb _ _ _ AB) as GSB. rewrite (proj1 IMG) in GOT.
    (* [comment removed for export] *)
    zstep. zstep. zstep. clear GOT GSB.
    (* [comment removed for export] *)
    zstep. zstep. zstep. zstep.
    (* [comment removed for export] *)
    zstep.
    pose proof MPIINIT as SPI. unfold mpi_init_stmtA, A_MPI_INIT_ in SPI.
    (* [comment removed for export] *)
    initcallA SPI HIA h (A + 8) lo SCS0 OA (bv_unsigned sp + -32).
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "AFTER-INIT1:" g end.
    initcallA SPI HIA h (A + 24) lo SCS0 OA (bv_unsigned sp + -32).
    initcallA SPI HIA h (A + 40) lo SCS0 OA (bv_unsigned sp + -32).
    initcallA SPI HIA h (A + 56) lo SCS0 OA (bv_unsigned sp + -32).
    initcallA SPI HIA h (A + 72) lo SCS0 OA (bv_unsigned sp + -32).
    initcallA SPI HIA h (A + 88) lo SCS0 OA (bv_unsigned sp + -32).
    initcallA SPI HIA h (A + 104) lo SCS0 OA (bv_unsigned sp + -32).
    clear SPI.
    (* [comment removed for export] *)
    pose proof (rw_cells_split_CB asegs _ (A + 120) [] 20 (gsub junk 120 20) [] [8; 8; 4]%nat T0 eq_refl) as T0s. clear T0.
    cbn [mk_CB_cells app] in T0s.
    apply (rw_cells_CB8_C8' asegs _ (A + 120) [] _ _) in T0s. cbn [app] in T0s.
    apply (rw_cells_CB8_C8' asegs _ (A + 120) [_] _ _) in T0s. cbn [app] in T0s.
    apply (rw_cells_CB4_C4 asegs _ (A + 120) [_; _] _ _) in T0s. cbn [app] in T0s.
    zstep. zstep. zstep. zstep. zstep. zstep.
    all: match goal with |- evtA _ _ _ _ _ => idtac | |- ?g => idtac "STORE120-LEFT:" g end.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    (* [comment removed for export] *)
    pose proof (rw_cells_split_CB asegs _ (A + 144) [] 48 (gsub junk 144 48) [] [8; 8; 8; 8; 8; 8]%nat T2 eq_refl) as T2s. clear T2.
    cbn [mk_CB_cells app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [] _ _) in T2s. cbn [app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [_] _ _) in T2s. cbn [app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [_; _] _ _) in T2s. cbn [app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [_; _; _] _ _) in T2s. cbn [app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [_; _; _; _] _ _) in T2s. cbn [app] in T2s.
    apply (rw_cells_CB8_C8' asegs _ (A + 144) [_; _; _; _; _] _ _) in T2s. cbn [app] in T2s.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    zstep. zstep. zstep. zstep. zstep. zstep.
    lazymatch goal with |- evtA _ _ _ _ (MS _ _ _ _ _ ?mx _) => rename mx into m9 end.
    match goal with H : stk _ m9 lo _ |- _ => rename H into ST end.
    (* [comment removed for export] *)
    zstep. zstep. zstep. zstep.
    release_frame FR ST (bv_unsigned sp).
    zstep.
    assert (HT : rw_cells asegs m9 (A + 120)
                   ([C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C4 (Z_to_bv 64 0)] ++ [C4 (wof (gsub junk 140 4))] ++
                    [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)])).
    { apply (proj2 (rw_cells_app asegs m9 (A + 120) _ _)). split; [exact T0s|].
      cbn [cells_size csize Nat.add]. change (Z.of_nat 20) with 20. replace (A + 120 + 20) with (A + 140) by (clear; lia).
      apply (proj2 (rw_cells_app asegs m9 (A + 140) _ _)). split; [exact T1|].
      cbn [cells_size csize Nat.add]. change (Z.of_nat 4) with 4. replace (A + 140 + 4) with (A + 144) by (clear; lia). exact T2s. }
